# refnorm <datei> <arbeitsordner>: Report ohne Laufzeit, Zeitstempel des Laufs, Script-/Katalog-Hash und Pfade des Laufs (fuer Referenzvergleiche)
refnorm() { sed -E 's/[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2} (UTC|CET|CEST)/TS/; s/runtime=[0-9]+s/runtime=Ns/; s/_[0-9]{8}_[0-9]{6}/_TS/g; s#'"$2"'[^ ]*#WORK#g; s/script_sha256=[0-9a-f]+/script_sha256=X/; s/msg_sha256=[0-9a-f]+/msg_sha256=X/; s/ns_quickcheck [0-9]+\.[0-9]+ /ns_quickcheck V /; s/\(([0-9]+) (Tage|days)\)/(N \2)/g; s/\(([0-9]+) (Tag|day)\)/(N \2)/g; s/netscaler-quickcheck [0-9]+\.[0-9]+ /netscaler-quickcheck V /; s#/home/[^ )]*/netscaler-quickcheck/#REPO/#g; s#/var/nssnapshot/#REPO/#g' "$1"; }
